import java.io.*;

public class Main {
    static List<List<Integer>> subsetsWithSum(int[] nums, int target) {
        // Write your solution here
        return new ArrayList<>();
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int n = (int) in.nval;
        in.nextToken();
        int target = (int) in.nval;
        int[] nums = new int[n];
        for (int i = 0; i < n; i++) {
            in.nextToken();
            nums[i] = (int) in.nval;
        }
        List<List<Integer>> res = subsetsWithSum(nums, target);
        for (List<Integer> s : res) Collections.sort(s);
        res.sort((x, y) -> {
            for (int i = 0; i < Math.min(x.size(), y.size()); i++) {
                int c = Integer.compare(x.get(i), y.get(i));
                if (c != 0) return c;
            }
            return Integer.compare(x.size(), y.size());
        });
        StringBuilder sb = new StringBuilder();
        sb.append(res.size()).append("\n");
        for (List<Integer> s : res) {
            for (int i = 0; i < s.size(); i++) sb.append(s.get(i)).append(i + 1 < s.size() ? " " : "\n");
        }
        System.out.print(sb);
    }
}
